 5|/**
 6| * Assert a Unix socket filesystem entry is owner-only before the caller treats
 7| * the bind as live. Used to close the chmod-after-listen TOCTOU window: the
 8| * umask guard around the bind makes the socket owner-only at creation, and this
 9| * lstat is the fail-closed verification gate (foreign uid or any group/other
10| * bit ⇒ refuse to start instead of accepting the first frame on an exposed socket).
11| */
12|export function assertSecureSocket(socketPath: string): void {
13|  let info;
14|  try {
15|    info = lstatSync(socketPath);
16|  } catch (error) {
17|    throw new HeadlessError(
18|      "INTERNAL_ERROR",
19|      `Secure socket verification failed: unable to stat ${socketPath} (${(error as Error).message}).`,
20|    );
21|  }
22|  if (!info.isSocket()) {
23|    throw new HeadlessError(
24|      "INTERNAL_ERROR",
25|      `Secure socket verification failed: ${socketPath} is not a Unix socket.`,
26|    );
27|  }
28|  const mode = info.mode & 0o777;
29|  if ((mode & 0o077) !== 0) {
30|    throw new HeadlessError(
31|      "INTERNAL_ERROR",
32|      `Secure socket verification failed: ${socketPath} has permissive mode 0o${mode.toString(8)} (group/other bits present); refusing to accept on an exposed socket.`,
33|    );
34|  }
35|  const expectedUid = process.getuid();
36|  if (info.uid !== expectedUid) {
37|    throw new HeadlessError(
38|      "INTERNAL_ERROR",
39|      `Secure socket verification failed: ${socketPath} is owned by uid ${info.uid}, expected uid ${expectedUid}; refusing to use a foreign-owned trust root.`,
40|    );
41|  }
