 6|/**
 7| * Atomically write file contents using the tmp -> fsync -> rename pattern.
 8| *
 9| * Ported from ContextRelay's src/atomic-write.ts so the Headless ledger stays
10| * compatible with that reference runtime. Guarantees:
11| * - Readers never see a half-written file (rename is atomic on POSIX).
12| * - On successful return, contents are fsynced to disk.
13| * - On process death mid-write, the original file is unchanged.
14| *
15| * The tmp file lives in the same directory as the target so the rename is an
16| * intra-filesystem atomic operation.
17| */
18|export function atomicWriteFile(path: string, content: string | Buffer, opts: { mode?: number } = {}): void {
19|  const mode = opts.mode ?? 0o600;
20|  const dir = dirname(path);
21|  const tmp = join(dir, `.${basename(path)}.tmp-${randomBytes(6).toString("hex")}`);
22|  const data = typeof content === "string" ? Buffer.from(content, "utf8") : content;
23|
24|  const fd = openSync(tmp, "w", mode);
25|  try {
26|    let written = 0;
27|    while (written < data.length) {
28|      written += writeSync(fd, data, written, data.length - written, null);
29|    }
30|    fsyncSync(fd);
31|  } catch (err) {
32|    cleanupSync("atomic-write.close-after-write-failure", () => closeSync(fd));
33|    cleanupSync("atomic-write.unlink-temp-after-write-failure", () => unlinkSync(tmp));
34|    throw err;
